SELECT SUM(pallets) AS total_pallets_arrived 
FROM warehouse.shipments 
WHERE arrived_ts >= '2026-06-01' AND arrived_ts < '2026-07-01';

SELECT COUNT(DISTINCT bill_id) FROM (
SELECT bill_id, till_status,
       ROW_NUMBER() OVER (PARTITION BY bill_id ORDER BY ts DESC) as rn
FROM payments.pos_payments
WHERE ts >= '2026-06-01' AND ts < '2026-07-01'
) sub WHERE rn = 1 AND till_status != 'approved';
